import { useEffect, useState } from "react";
import api from "../api";
import AddLevelWithTestCases from "../AdminPannel/AddLevelWithTestCases";

export default function Problems() {
  const [problems, setProblems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 768);
  const [showForm, setShowForm] = useState(false);

  useEffect(() => {
    loadProblems();

    const onResize = () => setIsMobile(window.innerWidth < 768);
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, []);

  const loadProblems = async () => {
    setLoading(true);
    try {
      const res = await api.get("/problems");
      setProblems(res.data);
    } catch (err) {
      console.error("PROBLEMS ERROR:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm("Delete this problem?")) return;
    try {
      await api.delete(`/problems/${id}`);
      loadProblems(); // 🔥 always reload full list
    } catch {
      alert("Delete failed");
    }
  };

  if (loading) {
    return <h2 style={{ color: "#fff", padding: 20 }}>Loading problems...</h2>;
  }

  return (
    <div style={styles.container}>
      {/* HEADER */}
      <div style={styles.header}>
        <h2 style={styles.heading}>📘 Problems</h2>

        <button
          style={styles.addBtn}
          onClick={() => setShowForm((prev) => !prev)}
        >
          {showForm ? "❌ Close Form" : "➕ Add Problem"}
        </button>
      </div>

      {/* ADD FORM */}
      {showForm && (
        <div style={{ marginBottom: 20 }}>
          <AddLevelWithTestCases />

          <button
            style={{ ...styles.addBtn, marginTop: 10 }}
            onClick={() => {
              setShowForm(false); // ✅ form band
              loadProblems();     // ✅ ALL problems reload
            }}
          >
            🔄 Refresh All Problems
          </button>
        </div>
      )}

      {/* PROBLEMS LIST (ALWAYS VISIBLE) */}
      <div style={styles.card}>
        {problems.length === 0 ? (
          <p style={{ color: "#94a3b8" }}>No problems found</p>
        ) : isMobile ? (
          <div style={styles.mobileList}>
            {problems.map((p) => (
              <div key={p.id} style={styles.mobileCard}>
                <div style={styles.mobileRow}>
                  <span style={styles.label}>Title</span>
                  <span>{p.title}</span>
                </div>

                <div style={styles.mobileRow}>
                  <span style={styles.label}>Test Cases</span>
                  <pre style={styles.code}>
                    {p.test_cases || "No test cases"}
                  </pre>
                </div>

                <button
                  style={styles.deleteBtn}
                  onClick={() => handleDelete(p.id)}
                >
                  🗑 Delete
                </button>
              </div>
            ))}
          </div>
        ) : (
          <div style={{ overflowX: "auto" }}>
            <table style={styles.table}>
              <thead>
                <tr>
                  <th style={styles.th}>ID</th>
                  <th style={styles.th}>Title</th>
                  <th style={styles.th}>Test Cases</th>
                  <th style={styles.th}>Actions</th>
                </tr>
              </thead>
              <tbody>
                {problems.map((p, i) => (
                  <tr key={p.id} style={i % 2 ? styles.rowAlt : styles.row}>
                    <td style={styles.td}>{p.id}</td>
                    <td style={styles.td}>{p.title}</td>
                    <td style={styles.td}>
                      <pre style={styles.code}>
                        {p.test_cases || "No test cases"}
                      </pre>
                    </td>
                    <td style={styles.td}>
                      <button
                        style={styles.deleteBtn}
                        onClick={() => handleDelete(p.id)}
                      >
                        🗑 Delete
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

